import Foundation
import Testing

@testable import CodealitySwiftCore

private let workflow = ".github/workflows/codeality.yml"

private let dartWorkflow = """
    # Generated by codeality-dart init and codeality-swift init.
    name: codeality

    on:
      workflow_call:
      workflow_dispatch:

    permissions:
      contents: read

    jobs:
      dart-apps-mobile:
        name: codeality-dart (apps/mobile)
        runs-on: ubuntu-latest
        steps:
          - run: echo dart # keep this comment

    """

@Suite struct InitTests {
    func repo() -> Fixture {
        let fixture = Fixture()
        _ = runTool("git", ["init", "-q"], workingDirectory: fixture.root)
        fixture.write("ios/Runner/AppDelegate.swift", "")
        return fixture
    }

    func read(_ fixture: Fixture, _ path: String) -> String {
        (try? String(contentsOfFile: fixture.root + "/" + path, encoding: .utf8)) ?? ""
    }

    func plan(_ fixture: Fixture, ci: Bool = true) throws -> [PlannedFile] {
        try planInit(
            projectRoot: fixture.root, ci: ci, roots: ["ios/Runner"], testRoots: [],
            entrypoints: ["ios/Runner/AppDelegate.swift"])
    }

    @Test func planningWritesNothing() throws {
        let fixture = repo()
        let planned = try plan(fixture)
        #expect(planned.allSatisfy { $0.disposition == .create })
        #expect(!FileManager.default.fileExists(atPath: fixture.root + "/" + configFileName))
    }

    @Test func applyCreatesTheThreeConfigFiles() throws {
        let fixture = repo()
        _ = try applyInit(try plan(fixture, ci: false), force: false)
        let config = try loadConfig(projectRoot: fixture.root)
        #expect(config.roots == ["ios/Runner"])
        #expect(config.entrypoint == ["ios/Runner/AppDelegate.swift"])
        #expect(read(fixture, ".swift-format").contains("\"lineLength\""))
        #expect(read(fixture, ".swiftlint.yml").contains("line_length"))
    }

    @Test func aDifferingSwiftFormatIsAConflictAndForceReplacesIt() throws {
        let fixture = repo()
        fixture.write(".swift-format", "{}\n")
        fixture.write(configFileName, "roots: [Other]\n")
        let planned = try plan(fixture, ci: false)
        #expect(planned.first { $0.path.hasSuffix(".swift-format") }?.disposition == .conflict)
        #expect(planned.first { $0.path.hasSuffix(configFileName) }?.disposition == .unchanged)
        _ = try applyInit(planned, force: true)
        #expect(read(fixture, ".swift-format").contains("\"lineLength\""))
        #expect(read(fixture, configFileName) == "roots: [Other]\n")
    }

    @Test func theSwiftJobJoinsDartJobsAndLeavesThemByteIdentical() throws {
        let fixture = repo()
        fixture.write(workflow, dartWorkflow)
        let planned = try plan(fixture)
        #expect(planned.first { $0.path.hasSuffix(workflow) }?.disposition == .merge)
        _ = try applyInit(planned, force: false)
        let merged = read(fixture, workflow)
        #expect(merged.hasPrefix(dartWorkflow))
        #expect(merged.contains("\n  swift:\n"))
    }

    @Test func reRunningIsUnchangedAndAnEditedJobIsAConflict() throws {
        let fixture = repo()
        _ = try applyInit(try plan(fixture), force: false)
        #expect(try plan(fixture).first { $0.path.hasSuffix(workflow) }?.disposition == .unchanged)
        fixture.write(
            workflow, read(fixture, workflow).replacingOccurrences(of: "swift build -c release", with: "swift build"))
        #expect(try plan(fixture).first { $0.path.hasSuffix(workflow) }?.disposition == .conflict)
        _ = try applyInit(try plan(fixture), force: true)
        #expect(try plan(fixture).first { $0.path.hasSuffix(workflow) }?.disposition == .unchanged)
    }

    @Test func withNoOtherWorkflowAMinimalCallerIsPlanned() throws {
        let fixture = repo()
        let caller = try plan(fixture).first { $0.path.hasSuffix("quality.yml") }
        #expect(caller?.content?.contains("uses: ./.github/workflows/codeality.yml") == true)
    }

    @Test func generatedWorkflowsPassActionlint() throws {
        let fixture = repo()
        _ = try applyInit(try plan(fixture), force: false)
        let lint = runTool("actionlint", [], workingDirectory: fixture.root)
        if lint.missing { return }
        #expect(lint.exitCode == 0, "\(lint.stdout)\(lint.stderr)")
    }

    @Test func theCheckFlagExitsTwoOnAConflict() throws {
        let fixture = repo()
        fixture.write(".swift-format", "{}\n")
        let result = try runBinary(["init", "--project", fixture.root, "--root", "ios/Runner", "--check"])
        #expect(result.status == 2)
    }
}
